var objTable;
var sFromDate = "";
var sToDate   = "";

$(document).ready(function( )
{
	$("#frmRecord #BtnSame").button({ icons:{ primary:'ui-icon-copy' } });


	$("#frmRecord").accordion(
	{
		collapsible  :  false,
		header       :  "h3",
		heightStyle  :  "content",
		icons        :  { header:"ui-icon-circle-arrow-e", activeHeader:"ui-icon-circle-arrow-s" }
	});


	$("#frmRecord #txtDob, #frmQuick #txtQuickDob").datepicker(
	{
		showOn           :  "both",
		buttonImage      :  "images/icons/calendar.gif",
		buttonImageOnly  :  true,
		dateFormat       :  "yy-mm-dd",
		changeYear       :  true,
		yearRange        :  "-30:+0"
	});


	$("#frmRecord #txtRegistrationDate, #frmQuick #txtQuickRegistrationDate").datepicker(
	{
		showOn          : "both",
		buttonImage     :  "images/icons/calendar.gif",
		buttonImageOnly :  true,
		dateFormat      :  "yy-mm-dd",
		minDate         :  parseDate($("#frmRecord #txtRegistrationDate").attr("date"), true)
	});


	$("#frmRecord #txtDob, #frmQuick #txtQuickDob").mask("9999-99-99");
	$("#frmRecord #txtRegistrationDate, #frmQuick #txtQuickRegistrationDate").mask("9999-99-99");

	$("#frmRecord #txtPhone, #frmQuick #txtQuickPhone").mask("999-99999999");
	$("#frmRecord #txtMobile, #frmQuick #txtQuickMobile").mask("0399-9999999");
	$("#frmRecord #txtFatherCnicNo, #frmQuick #txtQuickFatherCnicNo").mask("99999-9999999-9");
	$("#frmRecord #txtFatherPhone").mask("999-99999999");
	$("#frmRecord #txtFatherMobile").mask("0399-9999999");
	$("#frmRecord #txtMotherCnicNo, #frmQuick #txtQuickMotherCnicNo").mask("99999-9999999-9");
	$("#frmRecord #txtMotherPhone").mask("999-99999999");
	$("#frmRecord #txtMotherMobile").mask("0399-9999999");


	$("#frmRecord #BtnSame").click(function( )
	{
		$("#frmRecord #txtFatherAddress").val($("#frmRecord #txtAddress").val( ));
		$("#frmRecord #ddFatherLocation").val($("#frmRecord #ddLocation").val( ));
		$("#frmRecord #txtFatherPostalCode").val($("#frmRecord #txtPostalCode").val( ));

		$("#frmRecord #txtMotherAddress").val($("#frmRecord #txtAddress").val( ));
		$("#frmRecord #ddMotherLocation").val($("#frmRecord #ddLocation").val( ));
		$("#frmRecord #txtMotherPostalCode").val($("#frmRecord #txtPostalCode").val( ));

		return false;
	});


	$("#frmRecord #txtRegistrationNo").blur(function( )
	{
		if ($("#frmRecord #txtRegistrationNo").val( ) == "")
			return;


		$.post("ajax/students/check-registration.php",
			{ RegistrationNo:$("#frmRecord #txtRegistrationNo").val( ) },

			function (sResponse)
			{
				if (sResponse == "USED")
				{
					showMessage("#frmRecord #RecordMsg", "info", "The specified Registration No is already used. Please specify another Registration No.");

					$("#frmRecord #DuplicateRegistration").val("1");
				}

				else
				{
					$("#frmRecord #RecordMsg").hide( );
					$("#frmRecord #DuplicateRegistration").val("0");
				}
			},

			"text");
	});


	$("#frmRecord #ddSchool").change(function( )
	{
		getClassesList("#frmRecord #ddSchool", "#frmRecord #ddClass");
	});


	$("#frmRecord #BtnReset").click(function( )
	{
		$("#frmRecord")[0].reset( );
		$("#frmRecord #RecordMsg").hide( );

		$("#frmRecord").accordion("option", "active", 0);
		$("#frmRecord #txtName").focus( );

		return false;
	});


	$("#frmRecord").submit(function( )
	{
		var objFV = new FormValidator("frmRecord", "RecordMsg");


		if (!objFV.validate("txtName", "B", "Please enter the Student Name."))
		{
			$("#frmRecord").accordion("option", "active", 0);

			return false;
		}

		if (!objFV.validate("ddGender", "B", "Please select the Gender."))
		{
			$("#frmRecord").accordion("option", "active", 0);

			return false;
		}

		if (!objFV.validate("txtDob", "B", "Please select the Date of Birth."))
		{
			$("#frmRecord").accordion("option", "active", 0);

			return false;
		}

		if (objFV.value("filePicture") != "")
		{
			if (!checkImage(objFV.value("filePicture")))
			{
				showMessage("#RecordMsg", "alert", "Invalid File Format. Please select an image file of type jpg, gif or png.");

				objFV.focus("filePicture");
				objFV.select("filePicture");

				$("#frmRecord").accordion("option", "active", 0);

				return false;
			}
		}


		if (!objFV.validate("txtAddress", "B", "Please enter the Address."))
		{
			$("#frmRecord").accordion("option", "active", 1);

			return false;
		}

		if (!objFV.validate("ddLocation", "B", "Please select the City/Town."))
		{
			$("#frmRecord").accordion("option", "active", 1);

			return false;
		}

		if (!objFV.validate("txtMobile", "B", "Please enter the Mobile No."))
		{
			$("#frmRecord").accordion("option", "active", 1);

			return false;
		}

		if (!objFV.validate("txtEmail", "E", "Please enter the valid Email Address."))
		{
			$("#frmRecord").accordion("option", "active", 1);

			return false;
		}


		if (!objFV.validate("ddSession", "B", "Please select the Session."))
		{
			$("#frmRecord").accordion("option", "active", 2);

			return false;
		}

		if (!objFV.validate("ddSchool", "B", "Please select the School."))
		{
			$("#frmRecord").accordion("option", "active", 2);

			return false;
		}

		if (!objFV.validate("ddClass", "B", "Please select the Class."))
		{
			$("#frmRecord").accordion("option", "active", 2);

			return false;
		}
/*
		if (!objFV.validate("txtRegistrationNo", "B", "Please enter the Registration No."))
		{
			$("#frmRecord").accordion("option", "active", 2);

			return false;
		}
*/
		if (!objFV.validate("txtRegistrationDate", "B", "Please select the Registration Date."))
		{
			$("#frmRecord").accordion("option", "active", 2);

			return false;
		}


		var objMinRegDate       = parseDate($("#frmRecord #txtRegistrationDate").attr("date"));
		var objRegistrationDate = parseDate($("#frmRecord #txtRegistrationDate").val( ));

		if (objRegistrationDate.getTime( ) <= objMinRegDate.getTime( ))
		{
			showMessage("#frmRecord #RecordMsg", "alert", "You cannot select this Registration Date (Old Dated entries are Restricted).");

			$("#frmRecord").accordion("option", "active", 2);

			return false;
		}


		if ($("#frmRecord #txtFeeDiscount").length == 1)
		{
			if (!objFV.validate("txtFeeAmount", "B,N", "Please enter a vlaid Registration Fee."))
			{
				$("#frmRecord").accordion("option", "active", 2);

				return false;
			}

			if (!objFV.validate("txtFeeDiscount", "B,N", "Please enter a vlaid Registration Fee Discount."))
			{
				$("#frmRecord").accordion("option", "active", 2);

				return false;
			}


			var iFeeAmount   = parseInt($("#frmRecord #txtFeeAmount").val( ));
			var iFeeDiscount = parseInt($("#frmRecord #txtFeeDiscount").val( ));


			if (isNaN(iFeeAmount))
				iFeeAmount = 0;

			if (isNaN(iFeeDiscount))
				iFeeDiscount = 0;


			if (iFeeDiscount > iFeeAmount)
			{
				showMessage("#frmRecord #RecordMsg", "info", "Invalid Registration Fee Discount, please enter a valid Discount.");

				$("#frmRecord").accordion("option", "active", 2);

				return false;
			}
		}		


		if (!objFV.validate("txtFatherName", "B", "Please enter the Father Name."))
		{
			$("#frmRecord").accordion("option", "active", 3);

			return false;
		}

		if (!objFV.validate("txtFatherAddress", "B", "Please enter the Address."))
		{
			$("#frmRecord").accordion("option", "active", 3);

			return false;
		}

		if (!objFV.validate("ddFatherLocation", "B", "Please select the City/Town."))
		{
			$("#frmRecord").accordion("option", "active", 3);

			return false;
		}

		if (!objFV.validate("txtFatherEmail", "E", "Please enter the valid Email Address."))
		{
			$("#frmRecord").accordion("option", "active", 3);

			return false;
		}

/*
		if (!objFV.validate("txtMotherName", "B", "Please enter the Mother Name."))
		{
			$("#frmRecord").accordion("option", "active", 4);

			return false;
		}

		if (!objFV.validate("txtMotherAddress", "B", "Please enter the Address."))
		{
			$("#frmRecord").accordion("option", "active", 4);

			return false;
		}

		if (!objFV.validate("ddMotherLocation", "B", "Please select the City/Town."))
		{
			$("#frmRecord").accordion("option", "active", 4);

			return false;
		}
*/
		if (!objFV.validate("txtMotherEmail", "E", "Please enter the valid Email Address."))
		{
			$("#frmRecord").accordion("option", "active", 4);

			return false;
		}


		if (objFV.value("DuplicateRegistration") == "1")
		{
			showMessage("#frmRecord #RecordMsg", "info", "The specified Registration No is already used. Please specify another Registration No.");

			objFV.focus("txtRegistrationNo");
			objFV.select("txtRegistrationNo");

			return false;
		}


		$("#frmRecord #BtnSave").attr('disabled', true);
		$("#frmRecord #RecordMsg").hide( );
	});






	$("#frmQuick #BtnSave").button({ icons:{ primary:'ui-icon-disk' } });
	$("#frmQuick #BtnReset").button({ icons:{ primary:'ui-icon-refresh' } });


	$("#frmQuick #txtQuickRegistrationNo").blur(function( )
	{
		if ($("#frmQuick #txtQuickRegistrationNo").val( ) == "")
			return;


		$.post("ajax/students/check-registration.php",
			{ RegistrationNo:$("#frmQuick #txtQuickRegistrationNo").val( ) },

			function (sResponse)
			{
				if (sResponse == "USED")
				{
					showMessage("#frmQuick #QuickMsg", "info", "The specified Registration No is already used. Please specify another Registration No.");

					$("#frmQuick #DuplicateQuick").val("1");
				}

				else
				{
					$("#frmQuick #QuickMsg").hide( );
					$("#frmQuick #DuplicateQuick").val("0");
				}
			},

			"text");
	});


	$("#frmQuick #ddQuickSchool").change(function( )
	{
		getClassesList("#frmQuick #ddQuickSchool", "#frmQuick #ddQuickClass");
	});


	$("#frmQuick #BtnReset").click(function( )
	{
		$("#frmQuick")[0].reset( );
		$("#frmQuick #QuickMsg").hide( );
		$("#frmQuick #txtQuickName").focus( );

		return false;
	});


	$("#frmQuick").submit(function( )
	{
		var objFV = new FormValidator("frmQuick", "QuickMsg");


		if (!objFV.validate("txtName", "B", "Please enter the Student Name."))
			return false;

		if (!objFV.validate("ddGender", "B", "Please select the Gender."))
			return false;

		if (!objFV.validate("txtDob", "B", "Please select the Date of Birth."))
			return false;


		if (objFV.value("filePicture") != "")
		{
			if (!checkImage(objFV.value("filePicture")))
			{
				showMessage("#QuickMsg", "alert", "Invalid File Format. Please select an image file of type jpg, gif or png.");

				objFV.focus("filePicture");
				objFV.select("filePicture");

				return false;
			}
		}


		if (!objFV.validate("txtAddress", "B", "Please enter the Address."))
			return false;

		if (!objFV.validate("ddLocation", "B", "Please select the City/Town."))
			return false;

		if (!objFV.validate("txtMobile", "B", "Please enter the Mobile No."))
			return false;

		if (!objFV.validate("txtFatherName", "B", "Please enter the Father Name."))
			return false;

/*
		if (!objFV.validate("txtMotherName", "B", "Please enter the Mother Name."))
			return false;
*/

		if (!objFV.validate("ddSession", "B", "Please select the Session."))
			return false;

		if (!objFV.validate("ddSchool", "B", "Please select the School."))
			return false;

		if (!objFV.validate("ddClass", "B", "Please select the Class."))
			return false;
/*
		if (!objFV.validate("txtRegistrationNo", "B", "Please enter the Registration No."))
			return false;
*/
		if (!objFV.validate("txtRegistrationDate", "B", "Please select the Registration Date."))
			return false;


		var objMinRegDate       = parseDate($("#frmQuick #txtQuickRegistrationDate").attr("date"));
		var objRegistrationDate = parseDate($("#frmQuick #txtQuickRegistrationDate").val( ));

		if (objRegistrationDate.getTime( ) <= objMinRegDate.getTime( ))
		{
			showMessage("#frmQuick #QuickMsg", "alert", "You cannot select this Registration Date (Old Dated entries are Restricted).");

			return false;
		}


		if ($("#frmQuick #txtQuickFeeDiscount").length == 1)
		{
			if (!objFV.validate("txtFeeAmount", "B,N", "Please enter a vlaid Registration Fee."))
				return false;

			if (!objFV.validate("txtFeeDiscount", "B,N", "Please enter a vlaid Registration Fee Discount."))
				return false;


			var iFeeAmount   = parseInt($("#frmQuick #txtQuickFeeAmount").val( ));
			var iFeeDiscount = parseInt($("#frmQuick #txtQuickFeeDiscount").val( ));


			if (isNaN(iFeeAmount))
				iFeeAmount = 0;

			if (isNaN(iFeeDiscount))
				iFeeDiscount = 0;


			if (iFeeDiscount > iFeeAmount)
			{
				showMessage("#frmQuick #QuickMsg", "info", "Invalid Registration Fee Discount, please enter a valid Discount.");

				return false;
			}
		}


		if (objFV.value("DuplicateQuick") == "1")
		{
			showMessage("#frmQuick #QuickMsg", "info", "The specified Registration No is already used. Please specify another Registration No.");

			objFV.focus("txtRegistrationNo");
			objFV.select("txtRegistrationNo");

			return false;
		}


		$("#frmQuick #BtnSave").attr('disabled', true);
		$("#frmQuick #QuickMsg").hide( );
	});






	if (parseInt($("#TotalRecords").val( )) > 100)
	{
		$("#frmFilters #BtnApply").button({ icons:{ primary:'ui-icon-refresh' } });
		$("#frmFilters #BtnRemove").button({ icons:{ primary:'ui-icon-cancel' } }).attr("disabled", true);


		$("#frmFilters #txtFromDate, #frmFilters #txtToDate").datepicker(
		{
		     showOn          : "both",
		     buttonImage     : "images/icons/calendar.gif",
		     buttonImageOnly : true,
		     dateFormat      : "yy-mm-dd"
		});


		$("#frmFilters #BtnApply").click(function( )
		{
			$("#BtnMultiDelete").hide( );

			if ($("#frmFilters #txtFromDate").val( ) == "" || $("#frmFilters #txtToDate").val( ) == "")
				return;

			if ($("#frmFilters #txtFromDate").val( ) == sFromDate && $("#frmFilters #txtToDate").val( ) == sToDate)
				return;


			sFromDate = $("#frmFilters #txtFromDate").val( );
			sToDate   = $("#frmFilters #txtToDate").val( );

			objTable.fnFilter($(this).val( ), 0);
			$("#frmFilters #BtnRemove").attr("disabled", false);
		});


		$("#frmFilters #BtnRemove").click(function( )
		{
			$("#frmFilters #txtFromDate, #frmFilters #txtToDate").val("");

			if (sFromDate == "" || sToDate == "")
				return;

			sFromDate = "";
			sToDate   = "";


			$("#BtnMultiDelete").hide( );

			objTable.fnFilter($(this).val( ), 0);
			$("#frmFilters #BtnRemove").attr("disabled", true);
		});



		objTable = $("#DataGrid").dataTable( { sDom            : '<"H"f<"toolbar"><"TableTools">>t<"F"ip>',
											   aoColumnDefs    : [ { bSortable:false, aTargets:[7] } ],
											   oLanguage       : { sEmptyTable:"No record found", sInfoEmpty:"0 records", sZeroRecords:"No matching record found" },
											   aaSorting       : [ [ 0, "desc" ] ],
											   bJQueryUI       : true,
											   sPaginationType : "full_numbers",
											   bPaginate       : true,
											   bLengthChange   : false,
											   iDisplayLength  : parseInt($("#RecordsPerPage").val( )),
											   bFilter         : true,
											   bSort           : true,
											   bInfo           : true,
											   bStateSave      : false,
											   bProcessing     : false,
											   bAutoWidth      : false,
											   bServerSide     : true,
											   sAjaxSource     : "ajax/students/get-registrations.php",

											   fnServerData    : function (sSource, aoData, fnCallback)
																 {
																		if ($("div.toolbar #School").length > 0)
																			aoData.push({ name:"School", value:$("div.toolbar #School").val( ) });

																		if ($("div.toolbar #Class").length > 0)
																			aoData.push({ name:"Class", value:$("div.toolbar #Class").val( ) });

																		if ($("div.toolbar #Session").length > 0)
																			aoData.push({ name:"Session", value:$("div.toolbar #Session").val( ) });

																		if ($("div.toolbar #Status").length > 0)
																			aoData.push({ name:"Status", value:$("div.toolbar #Status").val( ) });

																		if (sFromDate != "")
																			aoData.push({ name:"FromDate", value:sFromDate });

																		if (sToDate != "")
																			aoData.push({ name:"ToDate", value:sToDate });


																		$.getJSON(sSource, aoData, function(jsonData)
																		{
																			fnCallback(jsonData);


																			$("#DataGrid tbody tr").each(function(iIndex)
																			{
																				$(this).attr("id", $(this).find("img:first-child").attr("id"));
																				$(this).find("td:first-child").addClass("position");
																			});
																		});
																 },

											   fnDrawCallback  : function( )
																   {
																	   $(".details").tipTip( );
																   },

											   fnInitComplete  : function( )
																 {
																		$.post("ajax/students/get-registration-filters.php",
																			   {},

																			   function (sResponse)
																			   {
																				$("div.toolbar").html(sResponse);
																			   },

																			   "text");


																		var iSchool = 0;
																		var iClass  = 0;
																		var iStatus = 0;

																		$("#DataGrid thead tr th").each(function(iIndex)
																		{
																			if ($(this).text( ) == "School")
																				iSchool = iIndex;

																			if ($(this).text( ) == "Class")
																				iClass = iIndex;

																			if ($(this).text( ) == "Status")
																				iStatus = iIndex;
																		});

																		this.fnFilter("", iSchool);
																		this.fnFilter("", iClass);
																		this.fnFilter("", iStatus);
																 }
										   } );
	}

	else
	{
		objTable = $("#DataGrid").dataTable( { sDom            : '<"H"f<"toolbar"><"TableTools">>t<"F"ip>',
											   aoColumnDefs    : [ { bSortable:false, aTargets:[7] } ],
											   oLanguage       : { sEmptyTable:"No record found", sInfoEmpty:"0 records", sZeroRecords:"No matching record found" },
											   aaSorting       : [ [ 0, "desc" ] ],
											   bJQueryUI       : true,
											   sPaginationType : "full_numbers",
											   bPaginate       : true,
											   bLengthChange   : false,
											   iDisplayLength  : parseInt($("#RecordsPerPage").val( )),
											   bFilter         : true,
											   bSort           : true,
											   bInfo           : true,
											   bStateSave      : false,
											   bProcessing     : false,
											   bAutoWidth      : false,

											   fnDrawCallback  : function( )
															   {
																   $(".details").tipTip( );
															   },

											   fnInitComplete  : function( )
																 {
																	$.post("ajax/students/get-registration-filters.php",
																		   {},

																		   function (sResponse)
																		   {
																			$("div.toolbar").html(sResponse);
																		   },

																		   "text");


																	var iSchool = 0;
																	var iClass  = 0;
																	var iStatus = 0;

																	$("#DataGrid thead tr th").each(function(iIndex)
																	{
																		if ($(this).text( ) == "School")
																			iSchool = iIndex;

																		if ($(this).text( ) == "Class")
																			iClass = iIndex;

																		if ($(this).text( ) == "Status")
																			iStatus = iIndex;
																	});

																	this.fnFilter("", iSchool);
																	this.fnFilter("", iClass);
																	this.fnFilter("", iStatus);
																 }
											  } );
	}


	$(document).on("change", "div.toolbar #School", function( )
	{
		var objRows = objTable.fnGetNodes( );

		for (var i = 0; i < objRows.length; i ++)
			$(objRows[i]).removeClass("selected");

		$("#BtnMultiDelete").hide( );


		var iColumn = 0;

		$("#DataGrid thead tr th").each(function(iIndex)
		{
			if ($(this).text( ) == "School")
				iColumn = iIndex;
		});


		objTable.fnFilter($(this).val( ), iColumn);


		if (parseInt($("#TotalRecords").val( )) <= 100)
		{
			$("#DataGrid td.position").each(function(iIndex)
			{
				var objRow = objTable.fnGetPosition($(this).closest('tr')[0]);

				objTable.fnUpdate((iIndex + 1), objRow, 0);
			});

			objTable.fnDraw( );
		}
	});


	$(document).on("change", "div.toolbar #Class", function( )
	{
		var objRows = objTable.fnGetNodes( );

		for (var i = 0; i < objRows.length; i ++)
			$(objRows[i]).removeClass("selected");

		$("#BtnMultiDelete").hide( );


		var iColumn = 0;

		$("#DataGrid thead tr th").each(function(iIndex)
		{
			if ($(this).text( ) == "Class")
				iColumn = iIndex;
		});


		objTable.fnFilter($(this).val( ), iColumn);


		if (parseInt($("#TotalRecords").val( )) <= 100)
		{
			$("#DataGrid td.position").each(function(iIndex)
			{
				var objRow = objTable.fnGetPosition($(this).closest('tr')[0]);

				objTable.fnUpdate((iIndex + 1), objRow, 0);
			});

			objTable.fnDraw( );
		}
	});


	$(document).on("change", "div.toolbar #Status", function( )
	{
		var objRows = objTable.fnGetNodes( );

		for (var i = 0; i < objRows.length; i ++)
			$(objRows[i]).removeClass("selected");

		$("#BtnMultiDelete").hide( );


		var iColumn = 0;

		$("#DataGrid thead tr th").each(function(iIndex)
		{
			if ($(this).text( ) == "Status")
				iColumn = iIndex;
		});


		objTable.fnFilter($(this).val( ), iColumn);


		if (parseInt($("#TotalRecords").val( )) <= 100)
		{
			$("#DataGrid td.position").each(function(iIndex)
			{
				var objRow = objTable.fnGetPosition($(this).closest('tr')[0]);

				objTable.fnUpdate((iIndex + 1), objRow, 0);
			});

			objTable.fnDraw( );
		}
	});


