																	{ Registrations:sRegistrations },

																	function (sResponse)
																	{
																		var sParams = sResponse.split("|-|");

																		showMessage("#GridMsg", sParams[0], sParams[1]);

																		if (sParams[0] == "success")
																		{
																			 for (var i = 0; i < objSelectedRows.length; i ++)
																			  objTable.fnDeleteRow(objSelectedRows[i]);

																			  $("#BtnMultiDelete").hide( );
																		}
																	},

																	"text");

																$(this).dialog("close");
															},

												  Cancel  : function( )
															{
																$(this).dialog("close");
															}
								       }
						         });
		}
	});


	$(document).on("click", ".icnStatus", function(event)
	{
		var iRegistrationId = this.id;
		var iIndex          = objTable.fnGetPosition($(this).closest('tr')[0]);

		$.colorbox({ href:("students/edit-registration-status.php?RegistrationId=" + iRegistrationId + "&Index=" + iIndex), width:"600px", height:"600px", iframe:true, opacity:"0.50", overlayClose:true });

		event.stopPropagation( );
	});


	$(document).on("click", ".icnEdit", function(event)
	{
		var iRegistrationId = this.id;
		var iIndex          = objTable.fnGetPosition($(this).closest('tr')[0]);

		$.colorbox({ href:("students/edit-registration.php?RegistrationId=" + iRegistrationId + "&Index=" + iIndex), width:"1000px", maxWidth:"90%", height:"730px", maxHeight:"90%", iframe:true, opacity:"0.50", overlayClose:false });

		event.stopPropagation( );
	});


	$(document).on("click", ".icnView", function(event)
	{
		var iRegistrationId = this.id;

		$.colorbox({ href:("students/view-registration.php?RegistrationId=" + iRegistrationId), width:"1000px", maxWidth:"90%", height:"650px", maxHeight:"90%", iframe:true, opacity:"0.50", overlayClose:true });

		event.stopPropagation( );
	});


	$(document).on("click", ".icnDelete", function(event)
	{
		var iRegistrationId = this.id;
		var objRow          = objTable.fnGetPosition($(this).closest('tr')[0]);

		$("#ConfirmDelete").dialog( { resizable : false,
