																						if (sParams[0] == "success")
																						{
																							 for (var i = 0; i < objSelectedRows.length; i ++)
																								  objTable.fnDeleteRow(objSelectedRows[i]);

																							  $("#BtnMultiDelete").hide( );


																							  if ($("#SelectButtons").length == 1)
																							  {
																								if (objTable.fnGetNodes( ).length > 5 && $("#DataGrid .icnDelete").length > 0)
																									$("#SelectButtons").show( );

																								else
																									$("#SelectButtons").hide( );
																							  }
																						}
																					},

																					"text");

																				$(this).dialog("close");
																		   },

																 Cancel  : function( )
																		   {
																				$(this).dialog("close");
																		   }
													  }
											});
		}
	});



	$(document).on("click", "#DataGrid .icnEdit", function(event)
	{
		var iWithdrawalId = this.id;
		var iIndex        = objTable.fnGetPosition($(this).closest('tr')[0]);

		$.colorbox({ href:("students/edit-withdrawal.php?WithdrawalId=" + iWithdrawalId + "&Index=" + iIndex), width:"800px", height:"500px", iframe:true, opacity:"0.50", overlayClose:false });

		event.stopPropagation( );
