	$("#frmRecord #ddSchool").change(function( )
	{
		getClassSectionsList("#frmRecord #ddSchool", "#frmRecord #ddClass");
	});


	$("#frmRecord #ddSchool, #frmRecord #ddSession, #frmRecord #ddClass").change(function( )
	{
		getStudentsList("#frmRecord #ddSchool", "#frmRecord #ddSession", "#frmRecord #ddClass", "#frmRecord #ddStudent", "A,N");
	});


	$("#frmRecord #BtnReset").click(function( )
	{
		$('#frmRecord')[0].reset( );
		$("#RecordMsg").hide( );

		clearList("#frmRecord #ddStudent");

		if ($("#frmRecord select#ddSchool").length > 0)
		{
			clearList("#frmRecord #ddClass");

			$("#frmRecord #ddSchool").focus( );
		}

		else
			$("#frmRecord #ddSession").focus( );

		return false;
	});


	$("#frmRecord").submit(function( )
	{
		var objFV = new FormValidator("frmRecord", "RecordMsg");

		if (!objFV.validate("ddSchool", "B", "Please select the School."))
			return false;

		if (!objFV.validate("ddSession", "B", "Please select the Session."))
			return false;

		if (!objFV.validate("ddClass", "B", "Please select the Class/Section."))
			return false;

		if (!objFV.validate("ddStudent", "B", "Please select the Student."))
			return false;

		if (!objFV.validate("txtApplicationDate", "B", "Please select the Application Date."))
			return false;

		var objMinDate         = parseDate($("#txtApplicationDate").attr("date"));
		var objApplicationDate = parseDate($("#txtApplicationDate").val( ));

		if (objApplicationDate.getTime( ) <= objMinDate.getTime( ))
		{
			showMessage("#RecordMsg", "alert", "You cannot select this Application Date (Old Dated entries are Restricted).");

			return false;
		}


		if (!objFV.validate("txtWithdrawalDate", "B", "Please select the Withdrawal Date."))
			return false;		

		var objMinDate        = parseDate($("#txtWithdrawalDate").attr("date"));
		var objWithdrawalDate = parseDate($("#txtWithdrawalDate").val( ));

		if (objWithdrawalDate.getTime( ) <= objMinDate.getTime( ))
		{
			showMessage("#RecordMsg", "alert", "You cannot select this Withdrawal Date (Old Dated entries are Restricted).");

			return false;
		}

/*
		if (objWithdrawalDate.getTime( ) < objApplicationDate.getTime( ))
		{
			showMessage("#RecordMsg", "alert", "The Withdrawal Date cannot be less than Application Date.");

			return false;
		}
*/

		if (!objFV.validate("ddReason", "B", "Please select the Withdrawal Reason."))
			return false;


		$("#frmRecord #BtnSave").attr('disabled', true);
		$("#RecordMsg").hide( );
	});
});


function updateRecord(iWithdrawalId, iRow, sFields)
{
	if (parseInt($("#TotalRecords").val( )) <= 100)
	{
		$("#DataGrid thead tr th").each(function(iIndex)
		{
			if ($(this).text( ) == "Withdrawal Reason")
				objTable.fnUpdate(sFields[0], iRow, iIndex, false);

			else if ($(this).text( ) == "Withdrawal Date")
				objTable.fnUpdate(sFields[1], iRow, iIndex, false);

			else if ($(this).text( ) == "Status")
				objTable.fnUpdate(sFields[2], iRow, iIndex, false);			

			else if ($(this).text( ) == "Options")
				objTable.fnUpdate(sFields[3], iRow, iIndex, false);
		});


		$(".details").tipTip( );
	}

	else
		objTable.fnStandingRedraw( );


	$.post("ajax/students/get-withdrawal-filters.php",
	       {},

	       function (sResponse)
	       {
	       		var sSchool = "";
	       		var sClass  = "";
	       		var sReason = "";
				var sStatus = "";


	       		if ($("div.toolbar #School").length > 0)
	       			sSchool = $("div.toolbar #School").val( );

	       		if ($("div.toolbar #Class").length > 0)
	       			sClass = $("div.toolbar #Class").val( );

	       		if ($("div.toolbar #Reason").length > 0)
	       			sReason = $("div.toolbar #Reason").val( );

	       		if ($("div.toolbar #Status").length > 0)
	       			sStatus = $("div.toolbar #Status").val( );				


				$("div.toolbar").html(sResponse);


	       		if ($("div.toolbar #School").length > 0)
	       			$("div.toolbar #School").val(sSchool);

	       		if ($("div.toolbar #Class").length > 0)
	       			$("div.toolbar #Class").val(sClass);

	       		if ($("div.toolbar #Reason").length > 0)
	       			$("div.toolbar #Reason").val(sReason);

	       		if ($("div.toolbar #Status").length > 0)
	       			$("div.toolbar #Status").val(sStatus);
	       },

	       "text");
}


function updateOptions(iRow, sOptions)
{
	$("#DataGrid thead tr th").each(function(iIndex)
	{
		if ($(this).text( ) == "Options")
		{
			objTable.fnUpdate(sOptions, iRow, iIndex);

			$(".details").tipTip( );
		}
	});
}

