	$(document).on("change", "div.toolbar #Mode", function( )
	{
		var objRows = objTable.fnGetNodes( );

		for (var i = 0; i < objRows.length; i ++)
			$(objRows[i]).removeClass("selected");

		$("#BtnMultiDelete").hide( );


		var iColumn = 0;

		$("#DataGrid thead tr th").each(function(iIndex)
		{
			if ($(this).text( ) == "Mode")
				iColumn = iIndex;
		});


		objTable.fnFilter($(this).val( ), iColumn);


		if (parseInt($("#TotalRecords").val( )) <= 100)
		{
			$("#DataGrid td.position").each(function(iIndex)
			{
				var objRow = objTable.fnGetPosition($(this).closest('tr')[0]);

				objTable.fnUpdate((iIndex + 1), objRow, 0);
			});

			objTable.fnDraw( );
		}
	});



	$("#BtnSelectAll").click(function( )
	{
		var iSchool   = 0;
		var iCategory = 0;
		var iMode     = 0;

		$("#DataGrid thead tr th").each(function(iIndex)
		{
			if ($(this).text( ) == "School")
				iSchool = iIndex;

			if ($(this).text( ) == "Category")
				iCategory = iIndex;

			if ($(this).text( ) == "Mode")
				iMode = iIndex;
		});


		var objRows   = objTable.fnGetNodes( );
		var bSelected = false;


		if (parseInt($("#TotalRecords").val( )) <= 100)
		{
			var sSchool   = "";
			var sCategory = "";
			var sMode     = "";

			if ($("div.toolbar #School").length > 0)
				sSchool = $("div.toolbar #School").val( );

			if ($("div.toolbar #Category").length > 0)
				sCategory = $("div.toolbar #Category").val( );

			if ($("div.toolbar #Mode").length > 0)
				sMode = $("div.toolbar #Mode").val( );


			for (var i = 0; i < objRows.length; i ++)
			{
				if ( (sSchool == "" || sSchool == objTable.fnGetData(objRows[i])[iSchool]) &&
				     (sCategory == "" || sCategory == objTable.fnGetData(objRows[i])[iCategory]) &&
				     (sMode == "" || sMode == objTable.fnGetData(objRows[i])[iMode]) )
				{
					if (!$(objRows[i]).hasClass("selected"))
					{
						$(objRows[i]).addClass("selected");

						bSelected = true;
					}
				}

				else
					$(objRows[i]).removeClass("selected");
			}
		}

		else
		{
			for (var i = 0; i < objRows.length; i ++)
			{
				if (!$(objRows[i]).hasClass("selected"))
				{
					$(objRows[i]).addClass("selected");

					bSelected = true;
