	$(document).on("click", "#DataGrid .icnEdit", function(event)
	{
		var iReceiptId = this.id;
		var iIndex     = objTable.fnGetPosition($(this).closest('tr')[0]);

		$.colorbox({ href:("pettycash/edit-receipt.php?ReceiptId=" + iReceiptId + "&Index=" + iIndex), width:"750px", height:"580px", iframe:true, opacity:"0.50", overlayClose:false });

		event.stopPropagation( );
