			for (var i = 0; i < objRows.length; i ++)
			{
				if ( (sSchool == "" || sSchool == objTable.fnGetData(objRows[i])[iSchool]) &&
				     (sCategory == "" || sCategory == objTable.fnGetData(objRows[i])[iCategory]) &&
				     (sMode == "" || sMode == objTable.fnGetData(objRows[i])[iMode]) )
				{
					if (!$(objRows[i]).hasClass("selected"))
					{
						$(objRows[i]).addClass("selected");

						bSelected = true;
					}
				}

				else
					$(objRows[i]).removeClass("selected");
			}
		}

		else
		{
			for (var i = 0; i < objRows.length; i ++)
			{
				if (!$(objRows[i]).hasClass("selected"))
				{
					$(objRows[i]).addClass("selected");

					bSelected = true;
				}
			}
		}

		if (bSelected == true)
			$("#BtnMultiDelete").show( );
	});


	$("#BtnSelectNone").click(function( )
	{
		var objRows = objTable.fnGetNodes( );

		for (var i = 0; i < objRows.length; i ++)
			$(objRows[i]).removeClass("selected");

		$("#BtnMultiDelete").hide( );
	});


	$(document).on("click", "#DataGrid tr", function( )
	{
		if ($(this).find("img.icnDelete").length == 0)
			return false;


		if ($(this).hasClass("selected"))
			$(this).removeClass("selected");

		else
			$(this).addClass("selected");


		var bSelected = false;
		var objRows   = objTable.fnGetNodes( );

		for (var i = 0; i < objRows.length; i ++)
		{
			if ($(objRows[i]).hasClass("selected"))
			{
				bSelected = true;

				break;
			}
		}

		if (bSelected == true)
			$("#BtnMultiDelete").show( );

		else
			$("#BtnMultiDelete").hide( );
	});


	$("#tabs-1 .TableTools").prepend('<button id="BtnMultiDelete">Delete Selected Rows</button>');
	$("#BtnMultiDelete").button({ icons:{ primary:'ui-icon-trash' } });
	$("#BtnMultiDelete").hide( );


	$(document).on("click", "#BtnMultiDelete", function( )
	{
		var sExpenses       = "";
		var objSelectedRows = new Array( );

		var objRows = objTable.fnGetNodes( );

		for (var i = 0; i < objRows.length; i ++)
		{
			if ($(objRows[i]).hasClass("selected"))
			{
				if (sExpenses != "")
					sExpenses += ",";

				sExpenses += objRows[i].id;

				objSelectedRows.push(objRows[i]);
			}
		}

		if (sExpenses != "")
		{
			$("#ConfirmMultiDelete").dialog(   { resizable : false,
												 width     : 420,
												 height    : 110,
												 modal     : true,
												 buttons   : { "Delete" : function( )
																		   {
																				 $.post("ajax/pettycash/delete-expense.php",
																					{ Expenses:sExpenses },

																					function (sResponse)
																					{
																						var sParams = sResponse.split("|-|");

																						showMessage("#GridMsg", sParams[0], sParams[1]);

																						if (sParams[0] == "success")
																						{
																						 for (var i = 0; i < objSelectedRows.length; i ++)
																							  objTable.fnDeleteRow(objSelectedRows[i]);

																						  $("#BtnMultiDelete").hide( );


																						  if ($("#SelectButtons").length == 1)
																						  {
																							if (objTable.fnGetNodes( ).length > 5 && $("#DataGrid .icnDelete").length > 0)
																								$("#SelectButtons").show( );

																							else
																								$("#SelectButtons").hide( );
																						  }
																						}
																					},

																					"text");

																				$(this).dialog("close");
																		   },

																 Cancel  : function( )
																		   {
																				$(this).dialog("close");
																		   }
													  }
											});
		}
	});


	$(document).on("click", "#DataGrid .icnEdit", function(event)
	{
		var iExpenseId = this.id;
		var iIndex     = objTable.fnGetPosition($(this).closest('tr')[0]);

		$.colorbox({ href:("pettycash/edit-expense.php?ExpenseId=" + iExpenseId + "&Index=" + iIndex), width:"750px", height:"650px", iframe:true, opacity:"0.50", overlayClose:false });

		event.stopPropagation( );
	});


	$(document).on("click", "#DataGrid .icnView", function(event)
	{
		var iExpenseId = this.id;

		$.colorbox({ href:("pettycash/view-expense.php?ExpenseId=" + iExpenseId), width:"750px", height:"650px", iframe:true, opacity:"0.50", overlayClose:true });

		event.stopPropagation( );
	});


	$(document).on("click", ".icnToggle", function(event)
	{
		var objIcon = this;
		var objRow  = objTable.fnGetPosition($(this).closest('tr')[0]);

		$(objIcon).removeClass( ).addClass("icon");

		$.post("ajax/pettycash/toggle-expense-status.php",
			{ ExpenseId:objIcon.id },

			function (sResponse)
			{
				var sParams = sResponse.split("|-|");

				showMessage("#GridMsg", sParams[0], sParams[1]);


				if (sParams[0] == "success")
				{
					var iColumn = 0;

					$("#DataGrid thead tr th").each(function(iIndex)
					{
						if ($(this).text( ) == "Status")
							iColumn = iIndex;
					});


					if (objIcon.src.indexOf("success.png") != -1)
						objIcon.src = objIcon.src.replace("success.png", "error.png");

					else
						objIcon.src = objIcon.src.replace("error.png", "success.png");
				}

				$(objIcon).removeClass("icon").addClass("icnToggle");
			},

			"text");

		event.stopPropagation( );
	});


	$(document).on("click", "#DataGrid .icnDelete", function(event)
	{
		var iExpenseId = this.id;
		var objRow     = objTable.fnGetPosition($(this).closest('tr')[0]);

		$("#ConfirmDelete").dialog(   { resizable : false,
										width     : 420,
										height    : 110,
										modal     : true,
										buttons   : { "Delete" : function( )
																  {
																		$.post("ajax/pettycash/delete-expense.php",
																			{ Expenses:iExpenseId },

																			function (sResponse)
																			{
																				var sParams = sResponse.split("|-|");

																				showMessage("#GridMsg", sParams[0], sParams[1]);

																				if (sParams[0] == "success")
																					objTable.fnDeleteRow(objRow);


																				if ($("#SelectButtons").length == 1)
																				{
																					if (objTable.fnGetNodes( ).length > 5 && $("#DataGrid .icnDelete").length > 0)
																						$("#SelectButtons").show( );

																					else
																						$("#SelectButtons").hide( );
																				}
																			},

																			"text");

																		$(this).dialog("close");
																  },

														Cancel  : function( )
																  {
																		$(this).dialog("close");
																  }
											 }
									  });

		event.stopPropagation( );
	});


	$(document).on("click", "#DataGrid .icnCheque", function(event)
	{
		var iExpenseId = this.id;
		var iIndex     = objTable.fnGetPosition($(this).closest('tr')[0]);

		$.colorbox({ href:("pettycash/edit-expense-cheque.php?ExpenseId=" + iExpenseId + "&Index=" + iIndex), width:"400px", height:"420px", iframe:true, opacity:"0.50", overlayClose:false });

		event.stopPropagation( );
	});





	$("#txtStudent").autocomplete({ source:("ajax/get-students-list.php?School=" + $("#ddSchool").val( )), minLength:3 });


	$(document).on("keydown", "#txtStudent", function(e)
	{
		if (e.which == 8 || e.which == 46)
			$(this).val("");
	});	


	$("#frmRecord #ddSchool").change(function( )
	{
		getEmployeesList("#frmRecord #ddSchool", "", "", "", "#frmRecord #ddEmployee");

		$("#txtStudent").autocomplete({ source:("ajax/get-students-list.php?School=" + $("#ddSchool").val( )), minLength:3 });
	});


	$("#ddMode").change(function( )
	{
		if ($(this).val( ) == "BT" || $(this).val( ) == "CH")
		{
			if ($("#frmRecord #BankAccount").css('display') == "none")
				$("#frmRecord #BankAccount").show('blind');

			if ($(this).val( ) == "CH")
			{
				if ($("#frmRecord #ChequeDetails").css('display') == "none")
					$("#frmRecord #ChequeDetails").show('blind');
			}
		}

		else
		{
			if ($("#frmRecord #BankAccount").css('display') == "block")
				$("#frmRecord #BankAccount").hide( );
		}


		if ($(this).val( ) != "CH")
		{
			if ($("#frmRecord #ChequeDetails").css('display') == "block")
				$("#frmRecord #ChequeDetails").hide("blind");
		}
	});


	$("#frmRecord #ddBankAccount").change(function( )
	{
		clearList("#ddChequeBook");
		clearList("#ddChequeNo");

		if ($("#frmRecord #ddBankAccount").val( ) == "")
			return;


		$.post("ajax/get-cheque-books.php",
			{ BankAccount:$("#frmRecord #ddBankAccount").val( ) },

			function (sResponse)
			{
				$("#frmRecord #ddChequeBook").html(sResponse);
				$("#frmRecord #ddChequeBook").trigger("change");
			},

			"text");
	});


	$("#frmRecord #ddChequeBook").change(function( )
	{
		clearList("#ddChequeNo");

		if ($("#frmRecord #ddChequeBook").val( ) == "")
			return;


		$.post("ajax/get-cheque-nos.php",
			{ ChequeBook:$("#frmRecord #ddChequeBook").val( ) },

			function (sResponse)
			{
				$("#frmRecord #ddChequeNo").html(sResponse);
			},

			"text");
	});


	$("#frmRecord #BtnReset").click(function( )
	{
		$('#frmRecord')[0].reset( );
		$("#RecordMsg").hide( );
		$("#frmRecord #ddCategory").focus( );

		clearList("#frmRecord #ddEmployee");

		return false;
	});


	$("#frmRecord").submit(function( )
	{
		var objFV = new FormValidator("frmRecord", "RecordMsg");


		if (!objFV.validate("ddCategory", "B", "Please select the Category."))
			return false;

		if (!objFV.validate("txtTitle", "B", "Please enter the Expense Title."))
			return false;

		if (!objFV.validate("txtAmount", "B,N", "Please enter the valid Amount."))
			return false;

		if (!objFV.validate("ddMode", "B", "Please select the Expense Mode."))
			return false;

		if (objFV.value("ddMode") == "BT")
		{
			if (!objFV.validate("ddBankAccount", "B", "Please select the Bank Account."))
				return false;
		}

		else if (objFV.value("ddMode") == "CH")
		{
			if (!objFV.validate("ddBankAccount", "B", "Please select the Bank Account."))
				return false;

			if (!objFV.validate("ddChequeBook", "B", "Please select the Cheque Book."))
				return false;

			if (!objFV.validate("ddChequeNo", "B", "Please select the Cheque No."))
				return false;

			if (!objFV.validate("txtChequeDate", "B", "Please select the Cheque Date."))
				return false;
		}

		if (!objFV.validate("txtDate", "B", "Please select the Expense Date."))
			return false;


		var objMinDate = parseDate($("#txtDate").attr("date"));

		if ($("#ddMode").val( ) == "CH" && $("#txtChequeDate").val( ) != "")
		{
			var objChequeDate = parseDate($("#txtChequeDate").val( ));

			if (objChequeDate.getTime( ) <= objMinDate.getTime( ))
			{
				showMessage("#RecordMsg", "alert", "You cannot select this Cheque Date (Old Dated entries are Restricted).");

				return false;
			}
		}


		var objDate = parseDate($("#txtDate").val( ));

		if (objDate.getTime( ) <= objMinDate.getTime( ))
		{
			showMessage("#RecordMsg", "alert", "You cannot select this Receipt Date (Old Dated entries are Restricted).");

			return false;
		}


		if (!objFV.validate("ddSchool", "B", "Please select the School."))
			return false;


		$("#frmRecord #BtnSave").attr('disabled', true);
		$("#RecordMsg").hide( );
	});
});


function updateRecord(iExpenseId, iRow, sFields)
{
	if (parseInt($("#TotalRecords").val( )) <= 100)
	{
		$("#DataGrid thead tr th").each(function(iIndex)
		{
			if ($(this).text( ) == "School")
				objTable.fnUpdate(sFields[0], iRow, iIndex, false);

			else if ($(this).text( ) == "Category")
				objTable.fnUpdate(sFields[1], iRow, iIndex, false);

			else if ($(this).text( ) == "Amount")
				objTable.fnUpdate(sFields[2], iRow, iIndex, false);

			else if ($(this).text( ) == "Date")
				objTable.fnUpdate(sFields[3], iRow, iIndex, false);

			else if ($(this).text( ) == "Mode")
				objTable.fnUpdate(sFields[4], iRow, iIndex, false);

			else if ($(this).text( ) == "Title")
				objTable.fnUpdate(sFields[5], iRow, iIndex, false);

			else if ($(this).text( ) == "Options")
				objTable.fnUpdate(sFields[6], iRow, iIndex, false);
		});

		$(".details").tipTip( );
	}

	else
		objTable.fnStandingRedraw( );
}


function updateOptions(iRow, sOptions)
{
	$("#DataGrid thead tr th").each(function(iIndex)
	{
		if ($(this).text( ) == "Options")
		{
			objTable.fnUpdate(sOptions, iRow, iIndex);

			$(".details").tipTip( );
		}
	});
}

