var objTable;
var sFromDate = "";
var sToDate   = "";

$(document).ready(function( )
{
	$("#frmRecord #BtnAddCredit, #frmRecord #BtnAddDebit").button({ icons:{ primary:'ui-icon-plus' } }).css("margin-left", "30px");
	$("#frmRecord .btnRemove").button({ icons:{ primary:'ui-icon-minus' },  text:false }).css({ position:"absolute", top:"6px", right:"6px" });
	$("#frmRecord .btnRemove span.ui-button-text").css("padding", "0px");
	$("#BtnImport").button({ icons:{ primary:'ui-icon-transferthick-e-w' } });


	$("#BtnImport").click(function( )
	{
		$.colorbox({ href:"accounts/import-voucher.php", width:"800px", maxWidth:"90%", height:"600px", maxHeight:"90%", iframe:true, opacity:"0.50", overlayClose:false });
	});
	


	$("#txtDate, #txtChequeDate").datepicker(
	{
		showOn          : "both",
		buttonImage     : "images/icons/calendar.gif",
		buttonImageOnly : true,
		dateFormat      : "yy-mm-dd",
		changeMonth     :  true,
		changeYear      :  true,
		minDate         :  parseDate($("#txtDate").attr("date"), true)
	});

	$("#txtDate, #txtChequeDate").mask("9999-99-99");



	$("#ddVoucherType, #txtDate").change(function( )
	{
		$("#txtVoucherNo").val("");
		
		
		if ($("#ddVoucherType").val( ) == "PV" || $("#ddVoucherType").val( ) == "RV")
		{
			if ($("#PaymentDetails").css('display') == "none")
				$("#PaymentDetails").show('blind');

			
			if ($("#ddVoucherType").val( ) == "PV")
			{
				$("#ChequeBook").show( );
				$("#Cheque").hide( );
			}
			
			else if ($("#ddVoucherType").val( ) == "RV")
			{
				$("#ChequeBook").hide( );
				$("#Cheque").show( );
			}

			$("#ddPaymentMethod").trigger("change");
		}

		else
		{
			if ($("#PaymentDetails").css('display') == "block")
			{
				$("#PaymentDetails").hide('blind');
				$("#ChequeDetails").hide('blind');				
				$("#ChequeBook").hide( );
				$("#Cheque").hide( );
			}
		}
		
		
		$.post("ajax/accounts/get-voucher-no.php",
			{ VoucherType:$("#ddVoucherType").val( ), VoucherDate:$("#txtDate").val( ) },

			function (sResponse)
			{
				if (sResponse != "")
					$("#txtVoucherNo").val(sResponse);
			},

			"text");
	});
	
	
	$("#ddPaymentMethod").change(function( )
	{
		if ($(this).val( ) == "CH")
		{
			if ($("#ChequeDetails").css('display') == "none")
				$("#ChequeDetails").show('blind');
		}

		else
		{
			if ($("#ChequeDetails").css('display') == "block")
				$("#ChequeDetails").hide('blind');
		}
	});
	
	
	$("#ddChequeBook").change(function( )
	{
		$.post("ajax/get-cheque-nos.php",
			{ ChequeBook:$("#ddChequeBook").val( ) },

			function (sResponse)
			{
				$("#ddChequeNo").html(sResponse);
			},

			"text");
	});


	setLedgersAutoComplete( );

	$(document).on("keydown", ".entry .ledger", function(e)
	{
		if (e.which == 8 || e.which == 46)
			$(this).val("");
	});


	$("#BtnAddCredit, #BtnAddDebit").click(function( )
	{
		var sSection = $(this).attr("id").replace("BtnAdd", "");
		var iIndex   = $("#" + sSection + " .entry").length;

	    $.post("ajax/accounts/get-voucher-entry.php",
		    { Index:iIndex, Section:sSection },

		    function (sResponse)
		    {
			  	$("#" + sSection).append(sResponse);

				$("#frmRecord .btnRemove").button({ icons:{ primary:'ui-icon-minus' },  text:false }).css({ position:"absolute", top:"6px", right:"6px" });
				$("#frmRecord .btnRemove span.ui-button-text").css("padding", "0px");

				$("#" + sSection + " #txt" + sSection + "Ledger" + iIndex).focus( );
				
				
				setLedgersAutoComplete( );
		    },

		    "text");

		return false;
	});


	$(document).on("click", ".entry .btnRemove", function( )
	{
		var sSection = $(this).parent( ).parent( ).attr("id");

		$(this).parent( ).remove( );


		$("#" + sSection + " .entry").each(function(iIndex)
		{
			$(this).attr("id", (sSection + iIndex));

			$(this).find(".ledger").attr("id", ("txt" + sSection + "Ledger" + iIndex));
			$(this).find(".ledger").parent( ).parent( ).find("label").attr("for", ("txt" + sSection + "Ledger" + iIndex));

			$(this).find(".particular").attr("id", ("txt" + sSection + "Particular" + iIndex));
			$(this).find(".particular").parent( ).parent( ).find("label").attr("for", ("txt" + sSection + "Particular" + iIndex));

			$(this).find(".amount" + sSection).attr("id", ("txt" + sSection + "Amount" + iIndex));
			$(this).find(".amount" + sSection).parent( ).parent( ).find("label").attr("for", ("txt" + sSection + "Amount" + iIndex));

			$(this).find("button").attr("rel", iIndex);
		});


		return false;
	});


	$(document).on("blur", ".entry .amountDebit, .entry .amountCredit", function( )
	{
		var fTotalDebit  = 0;
		var fTotalCredit = 0;

		$(".entry .amountDebit").each(function( )
		{
			if (!isNaN(parseFloat($(this).val( ))))
				fTotalDebit += parseFloat($(this).val( ));
		});

		$("#txtTotalDebit").val(fTotalDebit);
		
		
		if ($(".entry .amountDebit").length == 1 && $(".entry .amountCredit").length == 1)
		{
			if ($(".entry .amountCredit").val( ) == "")
				$(".entry .amountCredit").val(fTotalDebit);
		}
			


		$(".entry .amountCredit").each(function( )
		{
			if (!isNaN(parseFloat($(this).val( ))))
				fTotalCredit += parseFloat($(this).val( ));
		});

		$("#txtTotalCredit").val(fTotalCredit);


		if (fTotalDebit != fTotalCredit)
		{
			$("#txtTotalDebit").css("border-color", "#c44509");
			$("#txtTotalCredit").css("border-color", "#c44509");
		}

		else
		{
			$("#txtTotalDebit").css("border-color", "#739f1d");
			$("#txtTotalCredit").css("border-color", "#739f1d");
		}

		return false;
	});
	
	
	$(document).on("blur", "#Debit .entry .particular", function( )
	{
		var sCreditField = $(this).attr("id").replace("Debit", "Credit");
		
		if ($("#" + sCreditField).val( ) == "")
			$("#" + sCreditField).val($(this).val( ));
	});


	$("#frmRecord #BtnReset").click(function( )
	{
		$('#frmRecord')[0].reset( );
		$("#RecordMsg").hide( );
		$("#frmRecord #ddVoucherType").focus( );

		$("#Debit .entry").each(function(iIndex)
		{
			if (iIndex > 0)
				$(this).remove( );
		});

		$("#Credit .entry").each(function(iIndex)
		{
			if (iIndex > 0)
				$(this).remove( );
		});

		return false;
	});


	$("#frmRecord").submit(function( )
	{
		var objFV = new FormValidator("frmRecord", "RecordMsg");
		var bFlag = true;

		if (!objFV.validate("txtDate", "B", "Please select/enter the Date."))
			return false;
		
		if (objFV.value("ddVoucherType") == "PV" && objFV.value("ddPaymentMethod") == "CH")
		{
			if (!objFV.validate("txtPayeeName", "B", "Please enter the Payee Name."))
				return false;
			
			if (!objFV.validate("ddChequeBook", "B", "Please select the Cheque Book."))
				return false;
			
			if (!objFV.validate("ddChequeNo", "B", "Please select the Cheque No."))
				return false;
		}
		
		if ((objFV.value("ddVoucherType") == "PV" || objFV.value("ddVoucherType") == "RV") && objFV.value("ddPaymentMethod") == "CH")
		{
			if (!objFV.validate("txtChequeDate", "B", "Please select the Cheque Date."))
				return false;
		}

		
		if (!objFV.validate("ddSchool", "B", "Please select the School."))
			return false;
		
		if (objFV.value("fileInvoice") != "")
		{
			if (!checkDocument(objFV.value("fileInvoice")))
			{
				showMessage("#RecordMsg", "alert", "Invalid File Format. Please select a valid Invoice Document.");

				objFV.focus("fileInvoice");
				objFV.select("fileInvoice");

				return false;
			}
		}

		
		var objMinDate = parseDate($("#txtDate").attr("date"));
		
		if (($("#ddVoucherType").val( ) == "PV" || $("#ddVoucherType").val( ) == "RV") && $("#txtChequeDate").val( ) != "")
		{
			var objChequeDate = parseDate($("#txtChequeDate").val( ));
			
			if (objChequeDate.getTime( ) <= objMinDate.getTime( ))
			{
				showMessage("#RecordMsg", "alert", "You cannot select this Cheque Date (Old Dated entries are Restricted).");

				return false;
