function updateRecord(iVoucherId, iRow, sFields)
{
	if (parseInt($("#TotalRecords").val( )) <= 100)
	{
		$("#DataGrid thead tr th").each(function(iIndex)
		{
			if ($(this).text( ) == "Voucher No")
				objTable.fnUpdate(sFields[0], iRow, iIndex, false);
			
			else if ($(this).text( ) == "Amount")
				objTable.fnUpdate(sFields[1], iRow, iIndex, false);			

			else if ($(this).text( ) == "Payment Method")
				objTable.fnUpdate(sFields[2], iRow, iIndex, false);
			
			else if ($(this).text( ) == "School")
				objTable.fnUpdate(sFields[3], iRow, iIndex, false);
			
			else if ($(this).text( ) == "Date")
				objTable.fnUpdate(sFields[4], iRow, iIndex, false);

			else if ($(this).text( ) == "Options")
				objTable.fnUpdate(sFields[5], iRow, iIndex, false);
		});

		$(".details").tipTip( );
	}

	else
		objTable.fnStandingRedraw( );
}


