																		aoData.push({ name:"Type", value:$("div.toolbar #Type").val( ) });
																	
																	if ($("div.toolbar #PaymentMethod").length > 0)
																		aoData.push({ name:"PaymentMethod", value:$("div.toolbar #PaymentMethod").val( ) });

																	if ($("div.toolbar #Status").length > 0)
																		aoData.push({ name:"Status", value:$("div.toolbar #Status").val( ) });
																	
																	if (sFromDate != "")
																		aoData.push({ name:"FromDate", value:sFromDate });

																	if (sToDate != "")
																		aoData.push({ name:"ToDate", value:sToDate });


																	$.getJSON(sSource, aoData, function(jsonData)
																	{
																		fnCallback(jsonData);


																		$("#DataGrid tbody tr").each(function(iIndex)
																		{
																			$(this).attr("id", $(this).find("img:first-child").attr("id"));
																			$(this).find("td:first-child").addClass("position");
																		});
																	});
															   },

											 fnDrawCallback  : function( )
															   {
																   $(".details").tipTip( );
															   },

											 fnInitComplete  : function( )
															   {
																	$.post("ajax/accounts/get-voucher-filters.php",
																		   {},

																		   function (sResponse)
																		   {
																			$("div.toolbar").html(sResponse);
																		   },

																		   "text");


																	var iSchool        = 0;
																	var iType          = 0;
																	var iPaymentMethod = 0;

																	$("#DataGrid thead tr th").each(function(iIndex)
																	{
																		if ($(this).text( ) == "School")
																			iSchool = iIndex;

																		if ($(this).text( ) == "Voucher Type")
																			iType = iIndex;
																		
																		if ($(this).text( ) == "Payment Method")
																			iPaymentMethod = iIndex;
																	});

																	this.fnFilter("", iSchool);
																	this.fnFilter("", iType);
																	this.fnFilter("", iPaymentMethod);
															   }
										 } );
}
